diff --git a/src/stream.js b/src/stream.js
index 0e1a441..b8a95dc 100644
--- a/src/stream.js
+++ b/src/stream.js
@@ -1 +1,179 @@
-export async function openStream(options){throw Object.assign(new Error("NOT_IMPLEMENTED"),{code:"NOT_IMPLEMENTED"});}
+const VERSION = 1;
+const IDENTIFIER = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,63}$/;
+const MAX_SAFE = Number.MAX_SAFE_INTEGER;
+function fail(code) {
+  throw Object.assign(new Error(code), { code });
+}
+
+function storageError() {
+  return Object.assign(new Error('Storage operation failed'), { code: 'STORAGE_ERROR' });
+}
+
+function isPlainInput(value, allowed, required) {
+  if (value === null || typeof value !== 'object' || Array.isArray(value) || Object.getPrototypeOf(value) !== Object.prototype) return false;
+  const descriptors = Object.getOwnPropertyDescriptors(value);
+  for (const [key, descriptor] of Object.entries(descriptors)) {
+    if (!allowed.includes(key) || !descriptor.enumerable || !Object.hasOwn(descriptor, 'value')) return false;
+  }
+  return required.every((key) => Object.hasOwn(descriptors, key));
+}
+
+function validIdentifier(value) {
+  return typeof value === 'string' && IDENTIFIER.test(value);
+}
+
+function safeInteger(value, min = -MAX_SAFE) {
+  return Number.isSafeInteger(value) && value >= min;
+}
+
+function validateConfig(options) {
+  if (!isPlainInput(options, ['store', 'windowSize', 'allowedLateness', 'partitionIds'], ['store', 'windowSize', 'allowedLateness', 'partitionIds'])) fail('INVALID_INPUT');
+  const { store, windowSize, allowedLateness, partitionIds } = options;
+  if (!store || (typeof store !== 'object' && typeof store !== 'function') || typeof store.load !== 'function' || typeof store.compareAndSwap !== 'function') fail('INVALID_INPUT');
+  if (!safeInteger(windowSize, 1) || !safeInteger(allowedLateness, 0)) fail('INVALID_INPUT');
+  if (!Array.isArray(partitionIds) || partitionIds.length < 1 || partitionIds.length > 32 || !partitionIds.every(validIdentifier) || new Set(partitionIds).size !== partitionIds.length) fail('INVALID_INPUT');
+  return { store, windowSize, allowedLateness, partitionIds: [...partitionIds] };
+}
+
+function validateMethodInput(input, allowed, required) {
+  if (!isPlainInput(input, allowed, required)) fail('INVALID_INPUT');
+}
+
+function blankState(config) {
+  return { engineVersion: VERSION, config: { windowSize: config.windowSize, allowedLateness: config.allowedLateness, partitionIds: [...config.partitionIds] }, tenants: {} };
+}
+
+function validateState(state, config) {
+  if (state === null || typeof state !== 'object' || Array.isArray(state) || Object.getPrototypeOf(state) !== Object.prototype || state.engineVersion !== VERSION || !state.config || !state.tenants || typeof state.tenants !== 'object' || Array.isArray(state.tenants)) fail('CORRUPT_STORE');
+  const saved = state.config;
+  if (saved.windowSize !== config.windowSize || saved.allowedLateness !== config.allowedLateness || !Array.isArray(saved.partitionIds) || saved.partitionIds.length !== config.partitionIds.length || saved.partitionIds.some((id, i) => id !== config.partitionIds[i])) fail('CONFIG_MISMATCH');
+  if (Object.keys(state).sort().join(',') !== 'config,engineVersion,tenants') fail('CORRUPT_STORE');
+  for (const [tenantId, tenant] of Object.entries(state.tenants)) {
+    if (!validIdentifier(tenantId) || !tenant || typeof tenant !== 'object' || Array.isArray(tenant) || !tenant.watermarks || !tenant.events || !tenant.aggregates) fail('CORRUPT_STORE');
+    if (Object.keys(tenant.watermarks).some((id) => !config.partitionIds.includes(id) || !safeInteger(tenant.watermarks[id], 0))) fail('CORRUPT_STORE');
+    for (const event of Object.values(tenant.events)) {
+      if (!event || !validIdentifier(event.eventId) || !validIdentifier(event.partitionId) || !validIdentifier(event.key) || !safeInteger(event.timestamp, 0) || !safeInteger(event.value)) fail('CORRUPT_STORE');
+    }
+    for (const row of Object.values(tenant.aggregates)) {
+      if (!row || !validIdentifier(row.key) || !safeInteger(row.windowStart, 0) || !safeInteger(row.windowEnd, 0) || !safeInteger(row.count, 1) || !safeInteger(row.sum) || !safeInteger(row.min) || !safeInteger(row.max)) fail('CORRUPT_STORE');
+    }
+  }
+}
+
+async function loadState(store, config) {
+  let loaded;
+  try { loaded = await store.load(); } catch (error) {
+    // A JSON adapter can surface malformed persisted bytes as SyntaxError; that is corrupt data, not I/O.
+    if (error instanceof SyntaxError) fail('CORRUPT_STORE');
+    throw storageError();
+  }
+  if (!loaded || typeof loaded !== 'object' || !Number.isSafeInteger(loaded.version) || loaded.version < 0 || !Object.hasOwn(loaded, 'state')) fail('CORRUPT_STORE');
+  if (loaded.state === null) return { ...loaded, state: blankState(config), empty: true };
+  validateState(loaded.state, config);
+  return { ...loaded, empty: false };
+}
+
+async function commit(store, version, nextState) {
+  try { return await store.compareAndSwap(version, nextState); } catch { throw storageError(); }
+}
+
+function watermarksFor(tenant, config) {
+  const result = {};
+  for (const id of config.partitionIds) result[id] = tenant?.watermarks[id] ?? 0;
+  return result;
+}
+
+function globalWatermark(tenant, config) {
+  return Math.min(...Object.values(watermarksFor(tenant, config)));
+}
+
+function aggregateRow(row, tenantId, closed) {
+  return { tenantId, key: row.key, windowStart: row.windowStart, windowEnd: row.windowEnd, count: row.count, sum: row.sum, min: row.min, max: row.max, closed };
+}
+
+function isClosed(row, watermark, lateness) {
+  return watermark >= row.windowEnd + lateness;
+}
+
+export async function openStream(options) {
+  const config = validateConfig(options);
+  const { store } = config;
+  const loaded = await loadState(store, config);
+  if (loaded.empty && !(await commit(store, loaded.version, loaded.state))) fail('CONFLICT');
+
+  async function mutate(operation) {
+    for (let attempt = 0; attempt < 8; attempt += 1) {
+      const current = await loadState(store, config);
+      const draft = structuredClone(current.state);
+      const outcome = operation(draft);
+      if (outcome.noop) return structuredClone(outcome.result);
+      if (await commit(store, current.version, draft)) return structuredClone(outcome.result);
+    }
+    fail('CONFLICT');
+  }
+
+  async function ingest(input) {
+    validateMethodInput(input, ['tenantId', 'partitionId', 'eventId', 'key', 'timestamp', 'value'], ['tenantId', 'partitionId', 'eventId', 'key', 'timestamp', 'value']);
+    const { tenantId, partitionId, eventId, key, timestamp, value } = input;
+    if (![tenantId, partitionId, eventId, key].every(validIdentifier) || !config.partitionIds.includes(partitionId) || !safeInteger(timestamp, 0) || !safeInteger(value)) fail('INVALID_INPUT');
+    return mutate((state) => {
+      const tenant = state.tenants[tenantId] ?? { watermarks: {}, events: {}, aggregates: {} };
+      const prior = tenant.events[eventId];
+      if (prior) {
+        if (prior.partitionId !== partitionId || prior.eventId !== eventId || prior.key !== key || prior.timestamp !== timestamp || prior.value !== value) fail('IDEMPOTENCY_CONFLICT');
+        const start = Math.floor(timestamp / config.windowSize) * config.windowSize;
+        const end = start + config.windowSize;
+        const row = tenant.aggregates[`${start}:${key}`];
+        return { noop: true, result: { status: 'duplicate', windowStart: start, windowEnd: end, aggregate: aggregateRow(row, tenantId, isClosed(row, globalWatermark(tenant, config), config.allowedLateness)) } };
+      }
+      const start = Math.floor(timestamp / config.windowSize) * config.windowSize;
+      const end = start + config.windowSize;
+      if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) fail('AGGREGATE_OVERFLOW');
+      if (isClosed({ windowEnd: end }, globalWatermark(tenant, config), config.allowedLateness)) fail('TOO_LATE');
+      const aggregateKey = `${start}:${key}`;
+      const priorRow = tenant.aggregates[aggregateKey];
+      const count = (priorRow?.count ?? 0) + 1;
+      const sum = (priorRow?.sum ?? 0) + value;
+      if (!Number.isSafeInteger(count) || !Number.isSafeInteger(sum)) fail('AGGREGATE_OVERFLOW');
+      const row = { key, windowStart: start, windowEnd: end, count, sum, min: Math.min(priorRow?.min ?? value, value), max: Math.max(priorRow?.max ?? value, value) };
+      tenant.events[eventId] = { eventId, partitionId, key, timestamp, value };
+      tenant.aggregates[aggregateKey] = row;
+      state.tenants[tenantId] = tenant;
+      return { result: { status: 'accepted', windowStart: start, windowEnd: end, aggregate: aggregateRow(row, tenantId, isClosed(row, globalWatermark(tenant, config), config.allowedLateness)) } };
+    });
+  }
+
+  async function advanceWatermark(input) {
+    validateMethodInput(input, ['tenantId', 'partitionId', 'watermark'], ['tenantId', 'partitionId', 'watermark']);
+    const { tenantId, partitionId, watermark } = input;
+    if (!validIdentifier(tenantId) || !validIdentifier(partitionId) || !config.partitionIds.includes(partitionId) || !safeInteger(watermark, 0)) fail('INVALID_INPUT');
+    return mutate((state) => {
+      const tenant = state.tenants[tenantId] ?? { watermarks: {}, events: {}, aggregates: {} };
+      const previous = tenant.watermarks[partitionId] ?? 0;
+      if (watermark < previous) fail('WATERMARK_REGRESSION');
+      const before = globalWatermark(tenant, config);
+      if (watermark === previous) return { noop: true, result: { partitionWatermark: previous, globalWatermark: before, closedWindows: 0 } };
+      tenant.watermarks[partitionId] = watermark;
+      const after = globalWatermark(tenant, config);
+      const beforeClosed = new Set(Object.values(tenant.aggregates).filter((row) => isClosed(row, before, config.allowedLateness)).map((row) => row.windowStart));
+      const newlyClosed = new Set(Object.values(tenant.aggregates).filter((row) => isClosed(row, after, config.allowedLateness) && !beforeClosed.has(row.windowStart)).map((row) => row.windowStart));
+      state.tenants[tenantId] = tenant;
+      return { result: { partitionWatermark: watermark, globalWatermark: after, closedWindows: newlyClosed.size } };
+    });
+  }
+
+  async function query(input) {
+    validateMethodInput(input, ['tenantId', 'key'], ['tenantId']);
+    if (!validIdentifier(input.tenantId) || (Object.hasOwn(input, 'key') && !validIdentifier(input.key))) fail('INVALID_INPUT');
+    const current = await loadState(store, config);
+    const tenant = current.state.tenants[input.tenantId];
+    const watermark = globalWatermark(tenant, config);
+    const aggregates = Object.values(tenant?.aggregates ?? {})
+      .filter((row) => !Object.hasOwn(input, 'key') || row.key === input.key)
+      .sort((a, b) => a.windowStart - b.windowStart || (a.key < b.key ? -1 : a.key > b.key ? 1 : 0))
+      .map((row) => aggregateRow(row, input.tenantId, isClosed(row, watermark, config.allowedLateness)));
+    return { globalWatermark: watermark, partitionWatermarks: watermarksFor(tenant, config), aggregates };
+  }
+
+  return { ingest, advanceWatermark, query };
+}
diff --git a/tests/ingest-and-windows.test.js b/tests/ingest-and-windows.test.js
new file mode 100644
index 0000000..a63a9d6
--- /dev/null
+++ b/tests/ingest-and-windows.test.js
@@ -0,0 +1,257 @@
+import { expect, test } from 'vitest';
+import { createMemoryStore } from '../lib/stores.js';
+import { openStream } from '../src/stream.js';
+
+const MAX = Number.MAX_SAFE_INTEGER;
+const CONFIG = { windowSize: 10, allowedLateness: 2, partitionIds: ['p1', 'p2'] };
+
+async function errorOf(action) {
+  try {
+    await action();
+  } catch (error) {
+    return error;
+  }
+  return undefined;
+}
+
+test('[R-6][R-13][C-2] ingest returns accepted with half-open window bounds and the full aggregate row', async () => {
+  const stream = await openStream({ store: createMemoryStore(), ...CONFIG });
+
+  const result = await stream.ingest({
+    tenantId: 't1',
+    partitionId: 'p1',
+    eventId: 'e1',
+    key: 'k1',
+    timestamp: 9,
+    value: 5,
+  });
+
+  expect(result).toStrictEqual({
+    status: 'accepted',
+    windowStart: 0,
+    windowEnd: 10,
+    aggregate: {
+      tenantId: 't1',
+      key: 'k1',
+      windowStart: 0,
+      windowEnd: 10,
+      count: 1,
+      sum: 5,
+      min: 5,
+      max: 5,
+      closed: false,
+    },
+  });
+});
+
+test('[R-9][C-3] accepted events aggregate count, sum, min and max per tenant, key and window without cross-key effects', async () => {
+  const stream = await openStream({ store: createMemoryStore(), ...CONFIG });
+  const events = [
+    { eventId: 'e1', key: 'k1', timestamp: 1, value: 5 },
+    { eventId: 'e2', key: 'k1', timestamp: 2, value: -3 },
+    { eventId: 'e3', key: 'k1', timestamp: 8, value: 7 },
+    { eventId: 'e4', key: 'k2', timestamp: 3, value: 4 },
+  ];
+  for (const event of events) {
+    const result = await stream.ingest({ tenantId: 't1', partitionId: 'p1', ...event });
+    expect(result.status, event.eventId).toBe('accepted');
+  }
+
+  const query = await stream.query({ tenantId: 't1' });
+  expect(query.aggregates).toStrictEqual([
+    { tenantId: 't1', key: 'k1', windowStart: 0, windowEnd: 10, count: 3, sum: 9, min: -3, max: 7, closed: false },
+    { tenantId: 't1', key: 'k2', windowStart: 0, windowEnd: 10, count: 1, sum: 4, min: 4, max: 4, closed: false },
+  ]);
+});
+
+test('[R-6][C-8] window boundaries are half-open: timestamps 0 and 9 share [0,10) while timestamp 10 starts [10,20)', async () => {
+  const stream = await openStream({ store: createMemoryStore(), ...CONFIG });
+  const expected = [
+    [0, { windowStart: 0, windowEnd: 10 }],
+    [9, { windowStart: 0, windowEnd: 10 }],
+    [10, { windowStart: 10, windowEnd: 20 }],
+  ];
+
+  for (const [timestamp, bounds] of expected) {
+    const result = await stream.ingest({
+      tenantId: 't1',
+      partitionId: 'p1',
+      eventId: `ts${timestamp}`,
+      key: 'k1',
+      timestamp,
+      value: 1,
+    });
+    expect(result.status, `timestamp ${timestamp}`).toBe('accepted');
+    expect(result.windowStart, `timestamp ${timestamp} windowStart`).toBe(bounds.windowStart);
+    expect(result.windowEnd, `timestamp ${timestamp} windowEnd`).toBe(bounds.windowEnd);
+    expect(result.aggregate.windowStart, `timestamp ${timestamp} aggregate windowStart`).toBe(bounds.windowStart);
+  }
+});
+
+test('[R-6][C-9] window end overflow throws AGGREGATE_OVERFLOW without committing, while a window ending exactly at the safe maximum is accepted', async () => {
+  const overflowing = await openStream({
+    store: createMemoryStore(),
+    windowSize: 10,
+    allowedLateness: 2,
+    partitionIds: ['p1'],
+  });
+  const error = await errorOf(() =>
+    overflowing.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: MAX, value: 1 }),
+  );
+  expect(error?.code).toBe('AGGREGATE_OVERFLOW');
+  expect(await overflowing.query({ tenantId: 't1' })).toStrictEqual({
+    globalWatermark: 0,
+    partitionWatermarks: { p1: 0 },
+    aggregates: [],
+  });
+
+  const exact = await openStream({
+    store: createMemoryStore(),
+    windowSize: 1,
+    allowedLateness: 2,
+    partitionIds: ['p1'],
+  });
+  const result = await exact.ingest({
+    tenantId: 't1',
+    partitionId: 'p1',
+    eventId: 'e1',
+    key: 'k1',
+    timestamp: MAX - 1,
+    value: 1,
+  });
+  expect(result.status).toBe('accepted');
+  expect(result.windowStart).toBe(MAX - 1);
+  expect(result.windowEnd).toBe(MAX);
+  expect(result.aggregate.windowEnd).toBe(MAX);
+});
+
+test('[R-6][C-10] count-or-sum overflow in either direction throws AGGREGATE_OVERFLOW and commits only the accepted events', async () => {
+  const stream = await openStream({ store: createMemoryStore(), ...CONFIG });
+
+  const first = await stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 1, value: MAX });
+  expect(first.status).toBe('accepted');
+  const positiveOverflow = await errorOf(() =>
+    stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e2', key: 'k1', timestamp: 2, value: 1 }),
+  );
+  expect(positiveOverflow?.code, 'positive sum overflow').toBe('AGGREGATE_OVERFLOW');
+
+  const third = await stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e3', key: 'k2', timestamp: 1, value: -MAX });
+  expect(third.status).toBe('accepted');
+  const negativeOverflow = await errorOf(() =>
+    stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e4', key: 'k2', timestamp: 2, value: -1 }),
+  );
+  expect(negativeOverflow?.code, 'negative sum overflow').toBe('AGGREGATE_OVERFLOW');
+
+  const query = await stream.query({ tenantId: 't1' });
+  expect(query.aggregates).toStrictEqual([
+    { tenantId: 't1', key: 'k1', windowStart: 0, windowEnd: 10, count: 1, sum: MAX, min: MAX, max: MAX, closed: false },
+    { tenantId: 't1', key: 'k2', windowStart: 0, windowEnd: 10, count: 1, sum: -MAX, min: -MAX, max: -MAX, closed: false },
+  ]);
+});
+
+test('[R-8][C-12] window end plus allowed lateness beyond the safe range is compared correctly for both lateness extremes', async () => {
+  const largeLateness = await openStream({
+    store: createMemoryStore(),
+    windowSize: MAX,
+    allowedLateness: MAX,
+    partitionIds: ['p1'],
+  });
+  const ingested = await largeLateness.ingest({
+    tenantId: 't1',
+    partitionId: 'p1',
+    eventId: 'e1',
+    key: 'k1',
+    timestamp: 0,
+    value: 1,
+  });
+  expect(ingested.status).toBe('accepted');
+  expect(ingested.windowEnd).toBe(MAX);
+  const largeAdvance = await largeLateness.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: MAX });
+  expect(largeAdvance.closedWindows, 'window not closed when end + lateness exceeds safe range').toBe(0);
+  expect(largeAdvance.globalWatermark).toBe(MAX);
+
+  const zeroLateness = await openStream({
+    store: createMemoryStore(),
+    windowSize: MAX,
+    allowedLateness: 0,
+    partitionIds: ['p1'],
+  });
+  await zeroLateness.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 0, value: 1 });
+  const zeroAdvance = await zeroLateness.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: MAX });
+  expect(zeroAdvance.closedWindows, 'window closes on equality at the boundary').toBe(1);
+  const zeroQuery = await zeroLateness.query({ tenantId: 't1' });
+  expect(zeroQuery.aggregates[0].closed).toBe(true);
+});
+
+test('[R-16][C-15] identical event identities in different tenants are independent and do not cross tenant dedupe', async () => {
+  const stream = await openStream({ store: createMemoryStore(), ...CONFIG });
+
+  const t1 = await stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 1, value: 5 });
+  const t2 = await stream.ingest({ tenantId: 't2', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 1, value: 7 });
+  const replay = await stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 1, value: 5 });
+
+  expect(t1.status).toBe('accepted');
+  expect(t2.status, 'same eventId in another tenant').toBe('accepted');
+  expect(replay.status, 'exact replay within tenant').toBe('duplicate');
+
+  const q1 = await stream.query({ tenantId: 't1' });
+  const q2 = await stream.query({ tenantId: 't2' });
+  expect(q1.aggregates.map(({ count, sum }) => ({ count, sum }))).toStrictEqual([{ count: 1, sum: 5 }]);
+  expect(q2.aggregates.map(({ count, sum }) => ({ count, sum }))).toStrictEqual([{ count: 1, sum: 7 }]);
+});
+
+test('[R-9][C-35] event arrival order does not change count, sum, min, max, or closed flags across three stores', async () => {
+  const events = [
+    { partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 1, value: 5 },
+    { partitionId: 'p2', eventId: 'e2', key: 'k1', timestamp: 4, value: -3 },
+    { partitionId: 'p1', eventId: 'e3', key: 'k2', timestamp: 7, value: 8 },
+    { partitionId: 'p2', eventId: 'e4', key: 'k1', timestamp: 12, value: 2 },
+    { partitionId: 'p1', eventId: 'e5', key: 'k2', timestamp: 15, value: -6 },
+    { partitionId: 'p2', eventId: 'e6', key: 'k2', timestamp: 18, value: 4 },
+  ];
+  const orders = [
+    events,
+    [...events].reverse(),
+    [events[2], events[5], events[0], events[4], events[1], events[3]],
+  ];
+
+  const results = [];
+  for (const order of orders) {
+    const stream = await openStream({ store: createMemoryStore(), ...CONFIG });
+    for (const event of order) {
+      await stream.ingest({ tenantId: 't1', ...event });
+    }
+    await stream.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: 12 });
+    await stream.advanceWatermark({ tenantId: 't1', partitionId: 'p2', watermark: 12 });
+    results.push(await stream.query({ tenantId: 't1' }));
+  }
+
+  expect(results[1], 'reverse order').toStrictEqual(results[0]);
+  expect(results[2], 'shuffled order').toStrictEqual(results[0]);
+  expect(results[0].aggregates, 'directly computed aggregates').toStrictEqual([
+    { tenantId: 't1', key: 'k1', windowStart: 0, windowEnd: 10, count: 2, sum: 2, min: -3, max: 5, closed: true },
+    { tenantId: 't1', key: 'k2', windowStart: 0, windowEnd: 10, count: 1, sum: 8, min: 8, max: 8, closed: true },
+    { tenantId: 't1', key: 'k1', windowStart: 10, windowEnd: 20, count: 1, sum: 2, min: 2, max: 2, closed: false },
+    { tenantId: 't1', key: 'k2', windowStart: 10, windowEnd: 20, count: 2, sum: -2, min: -6, max: 4, closed: false },
+  ]);
+  expect(results[0].globalWatermark).toBe(12);
+});
+
+test('[R-7][R-9][C-39] a replay of an event in a closed window stays duplicate, while a new event there throws TOO_LATE and query is unchanged', async () => {
+  const stream = await openStream({ store: createMemoryStore(), ...CONFIG });
+  await stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+  await stream.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: 12 });
+  await stream.advanceWatermark({ tenantId: 't1', partitionId: 'p2', watermark: 12 });
+  const queryBefore = await stream.query({ tenantId: 't1' });
+  expect(queryBefore.aggregates[0].closed).toBe(true);
+
+  const replay = await stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+  expect(replay.status).toBe('duplicate');
+  expect(replay.aggregate).toStrictEqual(queryBefore.aggregates[0]);
+
+  const late = await errorOf(() =>
+    stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e9', key: 'k1', timestamp: 9, value: 1 }),
+  );
+  expect(late?.code).toBe('TOO_LATE');
+  expect(await stream.query({ tenantId: 't1' })).toStrictEqual(queryBefore);
+});
