@@ -0,0 +1,280 @@
+import { afterAll, expect, test } from 'vitest';
+import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { createFileStore, createMemoryStore } from '../lib/stores.js';
+import { openStream } from '../src/stream.js';
+
+const CONFIG = { windowSize: 10, allowedLateness: 2, partitionIds: ['p1', 'p2'] };
+const tempDirs = [];
+
+afterAll(async () => {
+  await Promise.all(tempDirs.map((dir) => rm(dir, { recursive: true, force: true })));
+});
+
+async function tempFile() {
+  const dir = await mkdtemp(join(tmpdir(), 'streamfold-'));
+  tempDirs.push(dir);
+  return join(dir, 'state.json');
+}
+
+function createSpyStore(backend = createMemoryStore()) {
+  const spy = { backend, loads: 0, casCalls: 0, forcedFalse: 0, beforeCas: null };
+  spy.store = {
+    async load() {
+      spy.loads += 1;
+      return backend.load();
+    },
+    async compareAndSwap(version, state) {
+      spy.casCalls += 1;
+      if (spy.beforeCas) {
+        const hook = spy.beforeCas;
+        spy.beforeCas = null;
+        await hook();
+      }
+      if (spy.forcedFalse > 0) {
+        spy.forcedFalse -= 1;
+        return false;
+      }
+      return backend.compareAndSwap(version, state);
+    },
+  };
+  return spy;
+}
+
+async function errorOf(action) {
+  try {
+    await action();
+  } catch (error) {
+    return error;
+  }
+  return undefined;
+}
+
+test('[R-2][R-7][R-16][C-20] reopening a file store with the same config restores query results, dedupe identities and watermarks', async () => {
+  const file = await tempFile();
+  const first = await openStream({ store: createFileStore(file), ...CONFIG });
+  await first.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+  await first.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: 5 });
+  await first.advanceWatermark({ tenantId: 't1', partitionId: 'p2', watermark: 5 });
+  const snapshot = await first.query({ tenantId: 't1' });
+
+  const reopened = await openStream({ store: createFileStore(file), ...CONFIG });
+  expect(await reopened.query({ tenantId: 't1' })).toStrictEqual(snapshot);
+
+  const replay = await reopened.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+  expect(replay.status).toBe('duplicate');
+
+  const regression = await errorOf(() =>
+    reopened.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: 4 }),
+  );
+  expect(regression?.code).toBe('WATERMARK_REGRESSION');
+
+  const fresh = await reopened.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e2', key: 'k1', timestamp: 1, value: 1 });
+  expect(fresh.status).toBe('accepted');
+});
+
+test('[R-7][C-21] after restart a replay in a closed window stays duplicate without any write while a new event there throws TOO_LATE', async () => {
+  const file = await tempFile();
+  const first = await openStream({ store: createFileStore(file), ...CONFIG });
+  await first.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+  await first.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: 12 });
+  await first.advanceWatermark({ tenantId: 't1', partitionId: 'p2', watermark: 12 });
+  const committed = await first.query({ tenantId: 't1' });
+
+  const spy = createSpyStore(createFileStore(file));
+  const reopened = await openStream({ store: spy.store, ...CONFIG });
+  const bytesBefore = await readFile(file);
+  spy.casCalls = 0;
+
+  const replay = await reopened.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+  expect(replay.status).toBe('duplicate');
+  expect(replay.aggregate).toStrictEqual(committed.aggregates[0]);
+  expect(spy.casCalls, 'CAS calls for replay').toBe(0);
+  expect((await readFile(file)).equals(bytesBefore), 'file bytes after replay').toBe(true);
+
+  const late = await errorOf(() =>
+    reopened.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e9', key: 'k1', timestamp: 9, value: 1 }),
+  );
+  expect(late?.code).toBe('TOO_LATE');
+  expect(await reopened.query({ tenantId: 't1' })).toStrictEqual(committed);
+});
+
+test('[R-2][C-22] reopening with a different window size, lateness, partition set or partition order throws CONFIG_MISMATCH without CAS or file writes', async () => {
+  const file = await tempFile();
+  const first = await openStream({ store: createFileStore(file), ...CONFIG });
+  await first.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+  const bytesBefore = await readFile(file);
+
+  const mismatches = [
+    { windowSize: 11 },
+    { allowedLateness: 3 },
+    { partitionIds: ['p2', 'p1'] },
+    { partitionIds: ['p1'] },
+    { partitionIds: ['p1', 'p2', 'p3'] },
+  ];
+  for (const override of mismatches) {
+    const label = JSON.stringify(override);
+    const spy = createSpyStore(createFileStore(file));
+    const error = await errorOf(() => openStream({ store: spy.store, ...CONFIG, ...override }));
+    expect(error?.code, label).toBe('CONFIG_MISMATCH');
+    expect(spy.casCalls, `${label}: CAS calls`).toBe(0);
+    expect((await readFile(file)).equals(bytesBefore), `${label}: file bytes`).toBe(true);
+  }
+});
+
+test('[R-3][C-23] corrupt, truncated or empty persisted files throw CORRUPT_STORE from openStream and are never reset or overwritten', async () => {
+  const validFile = await tempFile();
+  const valid = await openStream({ store: createFileStore(validFile), ...CONFIG });
+  await valid.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+  const validText = await readFile(validFile, 'utf8');
+
+  const cases = [
+    ['unterminated brace', '{'],
+    ['empty file', ''],
+    ['truncated state', validText.slice(0, Math.floor(validText.length / 2))],
+  ];
+  for (const [label, content] of cases) {
+    const file = await tempFile();
+    await writeFile(file, content);
+    const bytesBefore = await readFile(file);
+
+    const spy = createSpyStore(createFileStore(file));
+    const error = await errorOf(() => openStream({ store: spy.store, ...CONFIG }));
+    expect(error?.code, label).toBe('CORRUPT_STORE');
+    expect(spy.casCalls, `${label}: CAS calls`).toBe(0);
+    expect((await readFile(file)).equals(bytesBefore), `${label}: file bytes`).toBe(true);
+  }
+});
+
+test('[R-15][C-28] a CAS conflict after another instance commits reloads the latest state and returns a result that includes both commits', async () => {
+  const backend = createMemoryStore();
+  const spyA = createSpyStore(backend);
+  const streamA = await openStream({ store: spyA.store, ...CONFIG });
+  const streamB = await openStream({ store: backend, ...CONFIG });
+
+  spyA.loads = 0;
+  spyA.casCalls = 0;
+  spyA.beforeCas = () =>
+    streamB.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e2', key: 'k1', timestamp: 2, value: 7 });
+
+  const result = await streamA.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 1, value: 5 });
+
+  expect(result.status).toBe('accepted');
+  expect(result.aggregate).toStrictEqual({
+    tenantId: 't1',
+    key: 'k1',
+    windowStart: 0,
+    windowEnd: 10,
+    count: 2,
+    sum: 12,
+    min: 5,
+    max: 7,
+    closed: false,
+  });
+  expect(spyA.loads, 'loads by A').toBe(2);
+  expect(spyA.casCalls, 'CAS calls by A').toBe(2);
+});
+
+test('[R-15][C-29] a mutation succeeds on the eighth CAS attempt after seven conflicts and commits exactly once', async () => {
+  const spy = createSpyStore(createMemoryStore());
+  const stream = await openStream({ store: spy.store, ...CONFIG });
+
+  spy.forcedFalse = 7;
+  spy.casCalls = 0;
+  const ingested = await stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+  expect(ingested.status).toBe('accepted');
+  expect(spy.casCalls, 'CAS calls for ingest').toBe(8);
+
+  spy.forcedFalse = 7;
+  spy.casCalls = 0;
+  const advanced = await stream.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: 5 });
+  expect(advanced).toStrictEqual({ partitionWatermark: 5, globalWatermark: 0, closedWindows: 0 });
+  expect(spy.casCalls, 'CAS calls for advance').toBe(8);
+
+  const query = await stream.query({ tenantId: 't1' });
+  expect(query.partitionWatermarks.p1).toBe(5);
+  expect(query.aggregates[0]).toMatchObject({ count: 1, sum: 5 });
+});
+
+test('[R-15][C-30] when every CAS attempt returns false each mutation throws CONFLICT after eight attempts and returns nothing', async () => {
+  const backend = createMemoryStore();
+  const spy = createSpyStore(backend);
+  const stream = await openStream({ store: spy.store, ...CONFIG });
+  const before = await backend.load();
+
+  spy.forcedFalse = Infinity;
+  spy.casCalls = 0;
+  const ingestError = await errorOf(() =>
+    stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 }),
+  );
+  expect(ingestError?.code, 'ingest').toBe('CONFLICT');
+  expect(spy.casCalls, 'ingest CAS attempts').toBe(8);
+
+  spy.casCalls = 0;
+  const advanceError = await errorOf(() =>
+    stream.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: 5 }),
+  );
+  expect(advanceError?.code, 'advanceWatermark').toBe('CONFLICT');
+  expect(spy.casCalls, 'advanceWatermark CAS attempts').toBe(8);
+
+  expect(await backend.load(), 'state after exhausted attempts').toStrictEqual(before);
+});
+
+test('[R-7][R-15][C-32] concurrent identical ingests from two instances produce one accepted and one duplicate with no double count', async () => {
+  const file = await tempFile();
+  const streamA = await openStream({ store: createFileStore(file), ...CONFIG });
+  const streamB = await openStream({ store: createFileStore(file), ...CONFIG });
+  const event = { tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 };
+
+  const [a, b] = await Promise.all([streamA.ingest(event), streamB.ingest(event)]);
+
+  expect([a.status, b.status].sort()).toStrictEqual(['accepted', 'duplicate']);
+  const query = await streamA.query({ tenantId: 't1' });
+  expect(query.aggregates).toHaveLength(1);
+  expect(query.aggregates[0]).toMatchObject({ count: 1, sum: 5, min: 5, max: 5 });
+});
+
+test('[R-11][R-15][C-33] concurrent watermark advances on two partitions close the window exactly once and persist both partitions', async () => {
+  const file = await tempFile();
+  const seed = await openStream({ store: createFileStore(file), ...CONFIG });
+  await seed.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 9, value: 5 });
+
+  const streamA = await openStream({ store: createFileStore(file), ...CONFIG });
+  const streamB = await openStream({ store: createFileStore(file), ...CONFIG });
+  const [a, b] = await Promise.all([
+    streamA.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: 12 }),
+    streamB.advanceWatermark({ tenantId: 't1', partitionId: 'p2', watermark: 12 }),
+  ]);
+
+  expect(a.closedWindows + b.closedWindows, 'total newly closed windows').toBe(1);
+  expect(a.partitionWatermark).toBe(12);
+  expect(b.partitionWatermark).toBe(12);
+
+  const query = await streamA.query({ tenantId: 't1' });
+  expect(query.globalWatermark).toBe(12);
+  expect(query.partitionWatermarks).toStrictEqual({ p1: 12, p2: 12 });
+  expect(query.aggregates[0].closed).toBe(true);
+});
+
+test('[R-9][R-15][C-34] a conflict that reveals a closed window makes the reloaded ingest throw TOO_LATE and commit nothing from it', async () => {
+  const backend = createMemoryStore();
+  const spyA = createSpyStore(backend);
+  const streamA = await openStream({ store: spyA.store, ...CONFIG });
+  const streamB = await openStream({ store: backend, ...CONFIG });
+
+  await streamB.advanceWatermark({ tenantId: 't1', partitionId: 'p1', watermark: 12 });
+  const beforeRace = await backend.load();
+
+  spyA.beforeCas = () => streamB.advanceWatermark({ tenantId: 't1', partitionId: 'p2', watermark: 12 });
+  const error = await errorOf(() =>
+    streamA.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'e_new', key: 'k1', timestamp: 9, value: 1 }),
+  );
+
+  expect(error?.code).toBe('TOO_LATE');
+  const after = await backend.load();
+  expect(after.version, 'only the B commit advanced the version').toBe(beforeRace.version + 1);
+  const query = await streamB.query({ tenantId: 't1' });
+  expect(query.globalWatermark).toBe(12);
+  expect(query.aggregates).toStrictEqual([]);
+});
