+import { expect, test } from 'vitest';
+import { createMemoryStore } from '../lib/stores.js';
+import { openStream } from '../src/stream.js';
+
+const CONFIG = { windowSize: 10, allowedLateness: 2, partitionIds: ['p1'] };
+
+test('[R-3][R-4] unsupported persisted engine versions are corrupt and never overwritten', async () => {
+  let casCalls = 0;
+  const store = {
+    async load() {
+      return { version: 4, state: { engineVersion: 99, config: { ...CONFIG }, tenants: {} } };
+    },
+    async compareAndSwap() {
+      casCalls += 1;
+      return true;
+    },
+  };
+
+  await expect(openStream({ store, ...CONFIG })).rejects.toMatchObject({ code: 'CORRUPT_STORE' });
+  expect(casCalls).toBe(0);
+});
+
+test('[R-14] query remains read-only after openStream initializes the store', async () => {
+  const backend = createMemoryStore();
+  let casCalls = 0;
+  const store = {
+    load: () => backend.load(),
+    compareAndSwap: (...args) => {
+      casCalls += 1;
+      return backend.compareAndSwap(...args);
+    },
+  };
+  const stream = await openStream({ store, ...CONFIG });
+  casCalls = 0;
+
+  await expect(stream.query({ tenantId: 't1' })).resolves.toStrictEqual({
+    globalWatermark: 0,
+    partitionWatermarks: { p1: 0 },
+    aggregates: [],
+  });
+  expect(casCalls).toBe(0);
+});
