+import { expect, test } from 'vitest';
+import { createMemoryStore } from '../lib/stores.js';
+import { openStream } from '../src/stream.js';
+
+const MAX = Number.MAX_SAFE_INTEGER;
+const CONFIG = { windowSize: 10, allowedLateness: 2, partitionIds: ['p1', 'p2'] };
+const ERROR_CODES = [
+  'INVALID_INPUT',
+  'CONFIG_MISMATCH',
+  'WATERMARK_REGRESSION',
+  'TOO_LATE',
+  'IDEMPOTENCY_CONFLICT',
+  'AGGREGATE_OVERFLOW',
+  'CONFLICT',
+  'CORRUPT_STORE',
+  'STORAGE_ERROR',
+];
+
+function createSpyStore(backend = createMemoryStore()) {
+  const spy = {
+    backend,
+    loads: 0,
+    casCalls: 0,
+    loadFailFrom: Infinity,
+    loadError: new Error('EIO load'),
+    casFailing: false,
+    casError: new Error('EIO cas'),
+    forcedFalse: 0,
+    beforeCas: null,
+  };
+  spy.store = {
+    async load() {
+      spy.loads += 1;
+      if (spy.loads >= spy.loadFailFrom) throw spy.loadError;
+      return backend.load();
+    },
+    async compareAndSwap(version, state) {
+      spy.casCalls += 1;
+      if (spy.casFailing) throw spy.casError;
+      if (spy.beforeCas) {
+        const hook = spy.beforeCas;
+        spy.beforeCas = null;
+        await hook();
+      }
+      if (spy.forcedFalse > 0) {
+        spy.forcedFalse -= 1;
+        return false;
+      }
+      return backend.compareAndSwap(version, state);
+    },
+  };
+  return spy;
+}
+
+function fakeStore(state) {
+  return {
+    async load() {
+      return { version: 1, state };
+    },
+    async compareAndSwap() {
+      return true;
+    },
+  };
+}
+
+async function errorOf(action) {
+  try {
+    await action();
+  } catch (error) {
+    return error;
+  }
+  return undefined;
+}
+
+test('[R-2][C-1] openStream initializes a null store and an empty query reports zero watermarks and no aggregates', async () => {
+  const backend = createMemoryStore();
+  await openStream({ store: backend, ...CONFIG });
+
+  expect((await backend.load()).state, 'persisted state after open').not.toBeNull();
+  const stream = await openStream({ store: backend, ...CONFIG });
+  expect(await stream.query({ tenantId: 't1' })).toStrictEqual({
+    globalWatermark: 0,
+    partitionWatermarks: { p1: 0, p2: 0 },
+    aggregates: [],
+  });
+});
+
+test('[R-1][C-6] openStream accepts every boundary-valid configuration', async () => {
+  const cases = [
+    ['windowSize MAX_SAFE_INTEGER', { windowSize: MAX, allowedLateness: 0, partitionIds: ['p1'] }],
+    ['allowedLateness 0', { windowSize: 10, allowedLateness: 0, partitionIds: ['p1'] }],
+    ['allowedLateness MAX_SAFE_INTEGER', { windowSize: 10, allowedLateness: MAX, partitionIds: ['p1'] }],
+    [
+      '32 distinct partitions',
+      { windowSize: 10, allowedLateness: 2, partitionIds: Array.from({ length: 32 }, (_, i) => `p${i}`) },
+    ],
+    ['one-character partition id', { windowSize: 10, allowedLateness: 2, partitionIds: ['a'] }],
+    ['64-character partition id', { windowSize: 10, allowedLateness: 2, partitionIds: ['a'.repeat(64)] }],
+  ];
+
+  for (const [label, config] of cases) {
+    let stream;
+    const error = await errorOf(async () => {
+      stream = await openStream({ store: createMemoryStore(), ...config });
+    });
+    expect(error, label).toBeUndefined();
+
+    const query = await stream.query({ tenantId: 't1' });
+    expect(Object.keys(query.partitionWatermarks), label).toStrictEqual(config.partitionIds);
+  }
+});
+
+test('[R-1][C-7] openStream rejects invalid configuration values with INVALID_INPUT before any load or CAS', async () => {
+  const ids = (count) => Array.from({ length: count }, (_, i) => `p${i}`);
+  const base = { windowSize: 10, allowedLateness: 2, partitionIds: ['p1'] };
+  const cases = [
+    ...[0, -1, 1.5, '10', NaN, Infinity, MAX + 1, null].map((value) => [
+      `windowSize ${typeof value} ${String(value)}`,
+      { ...base, windowSize: value },
+    ]),
+    ...[-1, 1.5, MAX + 1].map((value) => [`allowedLateness ${String(value)}`, { ...base, allowedLateness: value }]),
+    ...[[], 'p1', ['p1', 'p1'], ids(33), ['-a'], ['a b'], ['a'.repeat(65)], [1], null].map((value) => [
+      `partitionIds ${typeof value} ${JSON.stringify(value)?.slice(0, 40)}`,
+      { ...base, partitionIds: value },
+    ]),
+  ];
+
+  for (const [label, config] of cases) {
+    const spy = createSpyStore();
+    const error = await errorOf(() => openStream({ store: spy.store, ...config }));
+    expect(error?.code, label).toBe('INVALID_INPUT');
+    expect(spy.loads, `${label}: load calls`).toBe(0);
+    expect(spy.casCalls, `${label}: CAS calls`).toBe(0);
+  }
+});
+
+test('[R-5][C-13] rejects malformed ingest, advanceWatermark and query inputs with INVALID_INPUT before CAS and without state change', async () => {
+  const backend = createMemoryStore();
+  const spy = createSpyStore(backend);
+  const stream = await openStream({ store: spy.store, ...CONFIG });
+  await stream.ingest({ tenantId: 't1', partitionId: 'p1', eventId: 'seed', key: 'k1', timestamp: 1, value: 1 });
+  const before = await backend.load();
+
+  const valid = { tenantId: 't1', partitionId: 'p1', eventId: 'e1', key: 'k1', timestamp: 1, value: 1 };
+  const withField = (overrides) => ({ ...valid, ...overrides });
+  const omit = (field) => Object.fromEntries(Object.entries(valid).filter(([name]) => name !== field));
+  class EventLike {
+    constructor() {
+      Object.assign(this, valid);
+    }
+  }
+  const getterEvent = withField({});
+  Object.defineProperty(getterEvent, 'value', { enumerable: true, get: () => 1 });
+  const nullPrototype = Object.assign(Object.create(null), valid);
+  const watermark = { tenantId: 't1', partitionId: 'p1', watermark: 1 };
+
+  const cases = [
+    ['ingest', 'null', null],
+    ['ingest', 'array', []],
+    ['ingest', 'Date', new Date()],
+    ['ingest', 'Map', new Map()],
+    ['ingest', 'class instance', new EventLike()],
+    ['ingest', 'null-prototype object', nullPrototype],
+    ['ingest', 'getter property', getterEvent],
+    ['ingest', 'extra key', withField({ extra: 1 })],
+    ['ingest', 'key undefined', withField({ key: undefined })],
+    ['ingest', 'unconfigured partitionId', withField({ partitionId: 'p9' })],
+    ['ingest', 'timestamp -1', withField({ timestamp: -1 })],
+    ['ingest', 'timestamp 1.5', withField({ timestamp: 1.5 })],
+    ['ingest', 'timestamp MAX+1', withField({ timestamp: MAX + 1 })],
+    ['ingest', 'timestamp string', withField({ timestamp: '9' })],
+    ['ingest', 'timestamp NaN', withField({ timestamp: NaN })],
+    ['ingest', 'value MAX+1', withField({ value: MAX + 1 })],
+    ['ingest', 'value NaN', withField({ value: NaN })],
+    ['ingest', 'value Infinity', withField({ value: Infinity })],
+    ['ingest', 'value 1.5', withField({ value: 1.5 })],
+    ['ingest', 'empty tenantId', withField({ tenantId: '' })],
+    ['ingest', 'tenantId with space', withField({ tenantId: 'a b' })],
+    ['ingest', 'tenantId 65 characters', withField({ tenantId: 'a'.repeat(65) })],
+    ['ingest', 'eventId leading dash', withField({ eventId: '-e' })],
+    ['ingest', 'eventId with space', withField({ eventId: 'e 1' })],
+    ['ingest', 'empty key', withField({ key: '' })],
+    ['ingest', 'key leading dot', withField({ key: '.k' })],
+    ['ingest', 'key 65 characters', withField({ key: 'k'.repeat(65) })],
+    ...Object.keys(valid).map((field) => ['ingest', `missing ${field}`, omit(field)]),
