+const MAX = Number.MAX_SAFE_INTEGER;
+const CONFIG = { windowSize: 10, allowedLateness: 2, partitionIds: ['p1', 'p2'] };
+
+function createSpyStore(backend = createMemoryStore()) {
+  const spy = { backend, loads: 0, casCalls: 0, forcedFalse: 0 };
+  spy.store = {
+    async load() {
+      spy.loads += 1;
+      return backend.load();
+    },
+    async compareAndSwap(version, state) {
+      spy.casCalls += 1;
+      if (spy.forcedFalse > 0) {
+        spy.forcedFalse -= 1;
+        return false;
+      }
+      return backend.compareAndSwap(version, state);
+    },
+  };
+  return spy;
+}
+
+async function errorOf(action) {
+  try {
+    await action();
+  } catch (error) {
+    return error;
+  }
+  return undefined;
+}
+
+function unsafeValuePaths(value, path = '$') {
+  if (value === undefined || typeof value === 'bigint' || typeof value === 'function' || typeof value === 'symbol') {
+    return [path];
+  }
+  if (typeof value === 'number' && !Number.isFinite(value)) return [path];
+  if (value instanceof Map || value instanceof Set) return [path];
+  if (value !== null && typeof value === 'object') {
+    return Object.entries(value).flatMap(([key, child]) => unsafeValuePaths(child, `${path}.${key}`));
+  }
+  return [];
+}
